            if (!overlap)
            {
                keep.Add(booked);
                continue;
            }

            if (booked.End - booked.Start < candidate.End - candidate.Start)
                resolved++;
            else if (booked.Start < candidate.Start)
                keep.Add(booked);
            else
                resolved++;
        }

        if (resolved > 0)
            _booked.Clear();

        foreach (var slot in keep)
            _booked.Add(slot);

        return resolved;
    }
}

internal sealed class NotificationService
{
    private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

    internal int Count => _notified.Count;

    internal bool Notify(Job job, PlacementService placement)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        if (_notified.Contains(job.Id))
            return false;
        if (!placement.IsPlaced(job.Id))
            return false;

        if (job.Priority > 8)
            _notified.Add(job.Id);
        else if (job.Priority > 0)
            _notified.Add(job.Id);
        else
            return false;

        return true;
    }

    internal string Escalate(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_notified.Contains(job.Id))
            return "not notified";
        if (job.Priority > 9)
            return "exec";
        if (job.Priority > 7)
            return "manager";
        if (job.Priority > 4)
            return "lead";
        if (job.Duration.TotalHours > 24)
            return "long-running";
        if (_notified.Count > 100 && job.Priority > 0)
            return "batch";

        return "none";
    }
}
